const r = await tools.exec_command({"cmd":"gh api --paginate 'repos/entireio/cli/pulls/comments?sort=created&direction=asc&since=2026-08-01T00%3A00%3A00Z&per_page=100' | jq -s 'add | map(select(.created_at < "2026-09-01T00:00:00Z"))' > /tmp/entire-cli-review-comments-2026-08.json
gh api graphql --paginate -f q='repo:entireio/cli is:pr updated:2026-08-01..2026-08-31' -f query='query($q: String!, $endCursor: String) { search(query: $q, type: ISSUE, first: 50, after: $endCursor) { pageInfo { hasNextPage endCursor } issueCount nodes { ... on PullRequest { number title url state createdAt closedAt mergedAt updatedAt author { login } additions deletions changedFiles reviews(first: 50) { totalCount nodes { author { login } state body submittedAt url } } reviewThreads(first: 1) { totalCount } comments(first: 1) { totalCount } } } } }' | jq -s '[.[].data.search.nodes[]]' > /tmp/entire-cli-prs-updated-2026-08.json
jq '{updated_prs:length, submitted_review_prs:([.[]|select(.reviews.totalCount>0)]|length), submitted_reviews:([.[].reviews.nodes[]]|length), nonempty_review_bodies:([.[].reviews.nodes[]|select(.body != "")]|length), authors:([.[].author.login]|unique|length)}' /tmp/entire-cli-prs-updated-2026-08.json
